            color = grid[sr][sc]
            if color == 0 or seen[sr][sc]:
                continue

            stack = [(sr, sc)]
            seen[sr][sc] = True
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        stack.append((nr, nc))

            r0 = min(r for r, c in cells)
            r1 = max(r for r, c in cells)
            c0 = min(c for r, c in cells)
            c1 = max(c for r, c in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            # Only fill components forming a complete rectangular outline.
            if not all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1 + 1)):
                continue
            if not all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1 + 1)):
                continue
            if any(grid[r][c] == color for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)):
